using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.RateLimiting;
using System.Threading.RateLimiting;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;

var builder = WebApplication.CreateBuilder(args);
var jwt = builder.Configuration.GetSection("Jwt");
if (builder.Environment.IsProduction() && (string.IsNullOrWhiteSpace(jwt["Key"]) || jwt["Key"]!.StartsWith("CHANGE_THIS"))) throw new InvalidOperationException("Production JWT key must be set through a secure environment variable.");
var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt["Key"]!));
var passwordHasher = new PasswordHasher<User>();
builder.Services.AddDbContext<BandSetDb>(o => o.UseNpgsql(builder.Configuration.GetConnectionString("BandSet")));
builder.Services.AddCors(o => o.AddDefaultPolicy(p => { var origins=builder.Configuration.GetSection("Cors:Origins").Get<string[]>(); if(builder.Environment.IsDevelopment()) p.AllowAnyHeader().AllowAnyMethod().AllowAnyOrigin(); else if(origins is { Length: > 0 }) p.WithOrigins(origins).AllowAnyHeader().AllowAnyMethod(); else throw new InvalidOperationException("Production CORS origins must be configured."); }));
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o => o.TokenValidationParameters = new() { ValidateIssuer=true, ValidIssuer=jwt["Issuer"], ValidateAudience=true, ValidAudience=jwt["Audience"], ValidateIssuerSigningKey=true, IssuerSigningKey=key, ValidateLifetime=true, ClockSkew=builder.Environment.IsDevelopment()?TimeSpan.FromDays(365):TimeSpan.FromMinutes(2) });
builder.Services.AddAuthorization();
builder.Services.AddRateLimiter(options => options.AddFixedWindowLimiter("auth", limiter => { limiter.PermitLimit=10; limiter.Window=TimeSpan.FromMinutes(1); limiter.QueueLimit=0; }));
builder.Services.AddHttpClient<PushService>();
var app = builder.Build(); if(!app.Environment.IsDevelopment()) app.UseHttpsRedirection(); app.UseCors(); app.UseRateLimiter(); app.UseAuthentication(); app.UseAuthorization();

app.MapGet("/health", async (BandSetDb db) => await db.Database.CanConnectAsync() ? Results.Ok(new { status="ok", database="connected" }) : Results.Problem(statusCode:503,title:"Database unavailable"));
app.MapGet("/api/band/members", async (BandSetDb db) => await db.Users.OrderBy(x=>x.Role=="Leader"?0:1).ThenBy(x=>x.Name).Select(x=>new { x.Id,x.Name,x.Instrument,x.Role }).ToListAsync()).RequireAuthorization();
app.MapGet("/api/notifications", async (ClaimsPrincipal principal, BandSetDb db) => { var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); return await db.Notifications.Where(x=>x.UserId==userId).OrderByDescending(x=>x.CreatedAt).Take(30).ToListAsync(); }).RequireAuthorization();
app.MapGet("/api/activity", async (BandSetDb db) => await db.Activities.OrderByDescending(x=>x.CreatedAt).Take(50).ToListAsync()).RequireAuthorization();
app.MapPost("/api/notifications/push-token", async (PushTokenRequest request, ClaimsPrincipal principal, BandSetDb db) => { if(string.IsNullOrWhiteSpace(request.Token)) return Results.BadRequest(); var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var entry=await db.PushTokens.SingleOrDefaultAsync(x=>x.Token==request.Token); if(entry is null) db.PushTokens.Add(new PushToken { UserId=userId,Token=request.Token }); else entry.UserId=userId; await db.SaveChangesAsync();return Results.NoContent(); }).RequireAuthorization();
app.MapPatch("/api/notifications/{id:int}/read", async (int id, ClaimsPrincipal principal, BandSetDb db) => { var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var notification=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==userId); if(notification is null)return Results.NotFound(); notification.IsRead=true;await db.SaveChangesAsync();return Results.NoContent(); }).RequireAuthorization();
app.MapPatch("/api/notifications/read-all", async (ClaimsPrincipal principal, BandSetDb db) => { var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); await db.Notifications.Where(x=>x.UserId==userId&&!x.IsRead).ExecuteUpdateAsync(x=>x.SetProperty(n=>n.IsRead,true)); return Results.NoContent(); }).RequireAuthorization();
app.MapGet("/api/dropbox/status", (IConfiguration config) => Results.Ok(new { configured=!string.IsNullOrWhiteSpace(config["Dropbox:AppKey"]), appKey=config["Dropbox:AppKey"] ?? "", redirectUri=config["Dropbox:RedirectUri"] ?? "bandset://dropbox-auth" })).RequireAuthorization();
app.MapPost("/api/auth/login", async (LoginRequest input, BandSetDb db) => {
  var user = await db.Users.SingleOrDefaultAsync(x => x.Email == input.Email);
  if (user is null || passwordHasher.VerifyHashedPassword(user, user.Password, input.Password) == PasswordVerificationResult.Failed) return Results.Unauthorized();
  // Мобильная сессия должна переживать обычные перезапуски приложения.
  var token = new JwtSecurityToken(jwt["Issuer"], jwt["Audience"], new[]{new Claim(ClaimTypes.NameIdentifier,user.Id.ToString()),new Claim(ClaimTypes.Role,user.Role)}, expires:DateTime.UtcNow.AddDays(30), signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));
  return Results.Ok(new { accessToken=new JwtSecurityTokenHandler().WriteToken(token), user=new { user.Id,user.Name,user.Email,user.Instrument,user.Role } });
}).RequireRateLimiting("auth");
app.MapPost("/api/auth/register", async (RegisterRequest input, BandSetDb db) => { var nickname=input.Nickname.Trim(); var role=input.Role=="Leader"?"Leader":"Musician"; var instrument=role=="Leader"?"Руководитель":input.Instrument?.Trim()??""; var allowedInstruments=new[]{"Вокалист","Гитара","Бас-гитара","Клавиши","Ударные"}; if (nickname.Length is < 2 or > 30 || string.IsNullOrWhiteSpace(input.Email) || input.Password.Length < 8) return Results.BadRequest(new { message="Никнейм должен содержать 2–30 символов, пароль — минимум 8." }); if(role=="Musician"&&!allowedInstruments.Contains(instrument)) return Results.BadRequest(new { message="Выберите инструмент участника." }); if (await db.Users.AnyAsync(x=>x.Email==input.Email || x.Name==nickname)) return Results.Conflict(new { message="Этот e-mail или никнейм уже занят." }); var user=new User { Name=nickname,Email=input.Email.Trim().ToLowerInvariant(),Instrument=instrument,Role=role }; user.Password=passwordHasher.HashPassword(user,input.Password); db.Users.Add(user);await db.SaveChangesAsync();return Results.Created($"/api/users/{user.Id}",new {user.Id,user.Name,user.Email,user.Instrument,user.Role}); }).RequireRateLimiting("auth");
app.MapGet("/api/concerts", async (BandSetDb db) => await db.Concerts.OrderBy(x=>x.Date).ToListAsync()).RequireAuthorization();
app.MapPost("/api/concerts", async (CreateConcertRequest request, BandSetDb db) => { if(string.IsNullOrWhiteSpace(request.Title)||string.IsNullOrWhiteSpace(request.Venue)) return Results.BadRequest(new { message="Название и место проведения обязательны." }); if(request.Date==default) return Results.BadRequest(new { message="Укажите корректную дату концерта." }); if(request.VotingDeadline is not null&&request.VotingDeadline>=request.Date) return Results.BadRequest(new { message="Дедлайн голосования должен быть раньше даты концерта." }); var concert=new Concert{Title=request.Title.Trim(),Date=request.Date.ToUniversalTime(),VotingDeadline=request.VotingDeadline?.ToUniversalTime(),Venue=request.Venue.Trim(),Description=request.Description?.Trim()??"",Status="Draft"}; db.Concerts.Add(concert); await db.SaveChangesAsync(); if(!request.SkipDefaultPlaylist){db.Playlists.Add(new Playlist{ConcertId=concert.Id,Name="Основной варіант"}); await db.SaveChangesAsync();} return Results.Created($"/api/concerts/{concert.Id}",concert); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapGet("/api/concerts/{id:int}/playlists", async (int id, BandSetDb db) => await db.Playlists.Where(x=>x.ConcertId==id).OrderBy(x=>x.Id).ToListAsync()).RequireAuthorization();
app.MapPost("/api/concerts/{id:int}/playlists", async (int id, CreatePlaylistRequest request, BandSetDb db) => { var concert=await db.Concerts.FindAsync(id); if(concert is null)return Results.NotFound(); if(concert.IsFinalized)return Results.BadRequest(new {message="Утверждённый плейлист нельзя изменять."}); var name=request.Name.Trim(); if(name.Length is < 1 or > 60)return Results.BadRequest(new {message="Название варианта должно содержать от 1 до 60 символов."}); if(await db.Playlists.AnyAsync(x=>x.ConcertId==id&&x.Name==name))return Results.Conflict(new {message="Вариант с таким названием уже существует."}); var playlist=new Playlist{ConcertId=id,Name=name};db.Playlists.Add(playlist);await db.SaveChangesAsync();return Results.Created($"/api/playlists/{playlist.Id}",playlist); }).RequireAuthorization(new AuthorizeAttribute {Roles="Leader"});
app.MapGet("/api/concerts/{id:int}/tracks", async (int id, int? playlistId, ClaimsPrincipal principal, BandSetDb db) => { var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var tracks=await db.Tracks.Where(x=>x.ConcertId==id&&(!playlistId.HasValue||x.PlaylistId==playlistId)).OrderBy(x=>x.SetNumber).ThenBy(x=>x.Position).ToListAsync(); var trackIds=tracks.Select(x=>x.Id).ToArray(); var votes=await db.Votes.Where(x=>trackIds.Contains(x.TrackId)).GroupBy(x=>x.TrackId).Select(x=>new { TrackId=x.Key, Yes=x.Count(v=>v.Value=="yes"), No=x.Count(v=>v.Value=="no"), Abstain=x.Count(v=>v.Value=="abstain") }).ToListAsync(); var ownVotes=await db.Votes.Where(x=>trackIds.Contains(x.TrackId)&&x.UserId==userId).ToDictionaryAsync(x=>x.TrackId,x=>x.Value); var response=tracks.Select(t=>{var vote=votes.FirstOrDefault(v=>v.TrackId==t.Id);return new { t.Id,t.Title,t.Artist,t.Position,t.SetNumber,t.Status,duration=t.Duration,key=t.Key,myVote=ownVotes.GetValueOrDefault(t.Id),votes=new {yes=vote?.Yes ?? 0,no=vote?.No ?? 0,abstain=vote?.Abstain ?? 0} };}); return Results.Ok(response); }).RequireAuthorization();
app.MapPost("/api/tracks/{id:int}/vote", async (int id, VoteRequest request, ClaimsPrincipal principal, BandSetDb db, PushService push) => { if(!new[]{"yes","no","abstain"}.Contains(request.Value)) return Results.BadRequest(new { message="Некорректное значение голоса." }); var track=await db.Tracks.FindAsync(id); if(track is null) return Results.NotFound(); var concert=await db.Concerts.FindAsync(track.ConcertId); if(concert is null) return Results.NotFound(); if(concert.Status!="Voting"||concert.IsFinalized) return Results.BadRequest(new { message="Голосование по этому концерту сейчас закрыто." }); if(track.Status!="Voting") return Results.BadRequest(new { message="Голосование по этой композиции сейчас закрыто." }); if(concert.VotingDeadline is not null && concert.VotingDeadline<=DateTime.UtcNow) return Results.BadRequest(new { message="Срок голосования истёк." }); var uid=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var voter=await db.Users.FindAsync(uid); var vote=await db.Votes.SingleOrDefaultAsync(x=>x.TrackId==id&&x.UserId==uid); if(vote is null) db.Votes.Add(new Vote{TrackId=id,UserId=uid,Value=request.Value}); else vote.Value=request.Value; db.Activities.Add(new Activity { Actor=voter?.Name ?? "Участник",Text=$"проголосовал за «{track.Title}»" }); var leaders=await db.Users.Where(user=>user.Role=="Leader"&&user.Id!=uid).Select(user=>user.Id).ToListAsync(); db.Notifications.AddRange(leaders.Select(leader=>new Notification { UserId=leader,TrackId=id,ConcertId=track.ConcertId,Title="Новый голос",Text=$"Получен голос по композиции «{track.Title}»." })); await db.SaveChangesAsync(); var tokens=await db.PushTokens.Where(token=>leaders.Contains(token.UserId)).Select(token=>token.Token).ToListAsync(); await push.Send(tokens,"Новый голос",$"Получен голос по композиции «{track.Title}»."); return Results.NoContent(); }).RequireAuthorization();
app.MapPost("/api/tracks/{id:int}/comments", async (int id, CommentRequest request, ClaimsPrincipal principal, BandSetDb db, PushService push) => { var text=request.Text.Trim(); if(text.Length is < 1 or > 1000) return Results.BadRequest(new { message="Комментарий должен содержать от 1 до 1000 символов." }); var track=await db.Tracks.FindAsync(id); if(track is null) return Results.NotFound(); if(await db.Concerts.AnyAsync(x=>x.Id==track.ConcertId&&x.IsFinalized)) return Results.BadRequest(new { message="Утверждённый плейлист нельзя изменять." }); var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var author=await db.Users.FindAsync(userId); var comment=new Comment { TrackId=id, UserId=userId, Text=text }; db.Comments.Add(comment); db.Activities.Add(new Activity { Actor=author?.Name ?? "Участник",Text=$"оставил комментарий к «{track.Title}»" }); var recipients=await db.Users.Where(user=>user.Id!=userId).Select(user=>user.Id).ToListAsync(); db.Notifications.AddRange(recipients.Select(recipient=>new Notification { UserId=recipient,TrackId=id,ConcertId=track.ConcertId,Title="Новый комментарий",Text=$"Новый комментарий к «{track.Title}»." })); await db.SaveChangesAsync(); var tokens=await db.PushTokens.Where(token=>recipients.Contains(token.UserId)).Select(token=>token.Token).ToListAsync(); await push.Send(tokens,"Новый комментарий",$"Новый комментарий к «{track.Title}». "); return Results.Created($"/api/comments/{comment.Id}",new { id=comment.Id,author=author?.Name ?? "Участник",text=comment.Text,createdAt=comment.CreatedAt }); }).RequireAuthorization();
app.MapGet("/api/tracks/{id:int}/comments", async (int id, BandSetDb db) => await (from comment in db.Comments where comment.TrackId==id join user in db.Users on comment.UserId equals user.Id orderby comment.CreatedAt select new { id=comment.Id,author=user.Name,text=comment.Text,createdAt=comment.CreatedAt }).ToListAsync()).RequireAuthorization();
app.MapPatch("/api/comments/{id:int}", async (int id, CommentRequest request, ClaimsPrincipal principal, BandSetDb db) => { var comment=await db.Comments.FindAsync(id); if(comment is null)return Results.NotFound(); var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); if(comment.UserId!=userId)return Results.Forbid(); var text=request.Text.Trim(); if(text.Length is < 1 or > 1000)return Results.BadRequest(new { message="Комментарий должен содержать от 1 до 1000 символов." }); comment.Text=text; await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapDelete("/api/comments/{id:int}", async (int id, ClaimsPrincipal principal, BandSetDb db) => { var comment=await db.Comments.FindAsync(id); if(comment is null)return Results.NotFound(); var userId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); if(comment.UserId!=userId)return Results.Forbid(); db.Comments.Remove(comment); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization();
app.MapPatch("/api/tracks/{id:int}/status", async (int id, TrackStatusRequest request, ClaimsPrincipal principal, BandSetDb db) => { var allowed=new[]{"Pending","Voting","Approved","Rejected","Replaced"}; if(!allowed.Contains(request.Status)) return Results.BadRequest(new { message="Некорректный статус трека." }); var track=await db.Tracks.FindAsync(id); if(track is null) return Results.NotFound(); if(await db.Concerts.AnyAsync(x=>x.Id==track.ConcertId&&x.IsFinalized)) return Results.BadRequest(new { message="Утверждённый плейлист нельзя изменять." }); track.Status=request.Status; var user=await db.Users.FindAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!)); db.Activities.Add(new Activity { Actor=user?.Name ?? "Руководитель",Text=$"изменил статус «{track.Title}» на {request.Status}" }); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapPut("/api/concerts/{id:int}/track-order", async (int id, TrackOrderRequest request, ClaimsPrincipal principal, BandSetDb db) => { if(await db.Concerts.AnyAsync(x=>x.Id==id&&x.IsFinalized)) return Results.BadRequest(new { message="Утверждённый плейлист нельзя изменять." }); var requested=await db.Tracks.Where(x=>x.ConcertId==id&&request.TrackIds.Contains(x.Id)).ToListAsync(); if(requested.Count==0||requested.Count!=request.TrackIds.Count||requested.Select(x=>x.PlaylistId).Distinct().Count()!=1) return Results.BadRequest(new { message="Передан неполный или некорректный список треков." }); var tracks=await db.Tracks.Where(x=>x.ConcertId==id&&x.PlaylistId==requested[0].PlaylistId).ToListAsync(); if(tracks.Count!=request.TrackIds.Count || tracks.Any(x=>!request.TrackIds.Contains(x.Id))) return Results.BadRequest(new { message="Передан неполный или некорректный список треков." }); for(var index=0;index<request.TrackIds.Count;index++) tracks.Single(x=>x.Id==request.TrackIds[index]).Position=index+1; var user=await db.Users.FindAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!));db.Activities.Add(new Activity { Actor=user?.Name ?? "Руководитель",Text="изменил порядок композиций" }); await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapPatch("/api/concerts/{id:int}/finalize", async (int id, ClaimsPrincipal principal, BandSetDb db, PushService push) => { var concert=await db.Concerts.FindAsync(id); if(concert is null) return Results.NotFound(); var tracks=await db.Tracks.Where(x=>x.ConcertId==id).ToListAsync(); if(tracks.Count==0) return Results.BadRequest(new { message="Нельзя утвердить пустой трек-лист." }); concert.IsFinalized=true; concert.Status="Approved"; var leaderId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!); var user=await db.Users.FindAsync(leaderId); var recipients=await db.Users.Where(x=>x.Id!=leaderId).Select(x=>x.Id).ToListAsync(); db.Notifications.AddRange(recipients.Select(userId=>new Notification{UserId=userId,ConcertId=id,Title="Трек-лист утверждён",Text=$"Трек-лист концерта «{concert.Title}» окончательно утверждён."})); db.Activities.Add(new Activity { Actor=user?.Name ?? "Руководитель",Text=$"утвердил трек-лист концерта «{concert.Title}»" }); await db.SaveChangesAsync(); var tokens=await db.PushTokens.Where(x=>recipients.Contains(x.UserId)).Select(x=>x.Token).ToListAsync(); await push.Send(tokens,"Трек-лист утверждён",$"Трек-лист концерта «{concert.Title}» окончательно утверждён."); return Results.NoContent(); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapPatch("/api/concerts/{id:int}/status", async (int id, ConcertStatusRequest request, ClaimsPrincipal principal, BandSetDb db, PushService push) => { var allowed=new[]{"Draft","Voting","Archived"}; if(!allowed.Contains(request.Status)) return Results.BadRequest(new { message="Некорректный статус концерта." }); var concert=await db.Concerts.FindAsync(id); if(concert is null) return Results.NotFound(); if(request.Status=="Voting"&&!await db.Tracks.AnyAsync(x=>x.ConcertId==id)) return Results.BadRequest(new { message="Сначала добавьте хотя бы одну композицию в трек-лист." }); concert.Status=request.Status; concert.IsFinalized=false; if(request.Status=="Voting"){var pendingTracks=await db.Tracks.Where(x=>x.ConcertId==id&&x.Status=="Pending").ToListAsync();foreach(var track in pendingTracks)track.Status="Voting";var leaderId=int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!);var leader=await db.Users.FindAsync(leaderId);var recipients=await db.Users.Where(x=>x.Id!=leaderId).Select(x=>x.Id).ToListAsync();db.Notifications.AddRange(recipients.Select(userId=>new Notification{UserId=userId,Title="Открыто голосование",Text=$"Концерт «{concert.Title}» ждёт вашего решения."}));db.Activities.Add(new Activity{Actor=leader?.Name??"Руководитель",Text=$"открыл голосование по концерту «{concert.Title}»"});await db.SaveChangesAsync();var tokens=await db.PushTokens.Where(x=>recipients.Contains(x.UserId)).Select(x=>x.Token).ToListAsync();await push.Send(tokens,"Открыто голосование",$"Концерт «{concert.Title}» ждёт вашего решения.");return Results.NoContent();} await db.SaveChangesAsync(); return Results.NoContent(); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapPost("/api/concerts/{id:int}/tracks", async (int id, CreateTrackRequest request, ClaimsPrincipal principal, BandSetDb db) => { var concert=await db.Concerts.FindAsync(id); if(concert is null) return Results.NotFound(); if(concert.IsFinalized) return Results.BadRequest(new { message="Утверждённый плейлист нельзя изменять." }); if(string.IsNullOrWhiteSpace(request.Title)||string.IsNullOrWhiteSpace(request.Artist)) return Results.BadRequest(new { message="Название и исполнитель обязательны." }); if(request.SetNumber is < 1 or > 4) return Results.BadRequest(new { message="Выберите сет от 1 до 4." }); var playlist=await db.Playlists.SingleOrDefaultAsync(x=>x.Id==request.PlaylistId&&x.ConcertId==id); if(playlist is null)return Results.BadRequest(new {message="Выберите вариант плейлиста."}); var position=(await db.Tracks.Where(x=>x.ConcertId==id&&x.PlaylistId==request.PlaylistId&&x.SetNumber==request.SetNumber).MaxAsync(x=>(int?)x.Position) ?? 0)+1; var track=new Track { ConcertId=id,PlaylistId=request.PlaylistId,Title=request.Title.Trim(),Artist=request.Artist.Trim(),Duration=request.Duration?.Trim()??"—",Key=request.Key?.Trim()??"—",SetNumber=request.SetNumber,Position=position,Status="Pending" }; db.Tracks.Add(track);var user=await db.Users.FindAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!));db.Activities.Add(new Activity { Actor=user?.Name ?? "Руководитель",Text=$"добавил композицию «{track.Title}» в вариант «{playlist.Name}», сет {track.SetNumber}" });await db.SaveChangesAsync();return Results.Created($"/api/tracks/{track.Id}",track); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
app.MapDelete("/api/tracks/{id:int}", async (int id, ClaimsPrincipal principal, BandSetDb db) => { var track=await db.Tracks.FindAsync(id);if(track is null)return Results.NotFound();if(await db.Concerts.AnyAsync(x=>x.Id==track.ConcertId&&x.IsFinalized)) return Results.BadRequest(new { message="Утверждённый плейлист нельзя изменять." });var title=track.Title;db.Tracks.Remove(track);var user=await db.Users.FindAsync(int.Parse(principal.FindFirstValue(ClaimTypes.NameIdentifier)!));db.Activities.Add(new Activity { Actor=user?.Name ?? "Руководитель",Text=$"удалил композицию «{title}»" });await db.SaveChangesAsync();return Results.NoContent(); }).RequireAuthorization(new AuthorizeAttribute { Roles="Leader" });
await Seed(app.Services); app.Run();

static async Task Seed(IServiceProvider services) { using var s=services.CreateScope(); var db=s.ServiceProvider.GetRequiredService<BandSetDb>(); await db.Database.MigrateAsync(); var leader=await db.Users.SingleOrDefaultAsync(x=>x.Email=="maria@blueecho.band"); if(leader is null) { leader=new User { Name="Володимир Алексеев",Email="maria@blueecho.band",Instrument="Руководитель",Role="Leader" }; leader.Password=new PasswordHasher<User>().HashPassword(leader,"demo123"); db.Users.Add(leader); } else { leader.Name="Володимир Алексеев"; leader.Instrument="Руководитель"; leader.Role="Leader"; } await db.SaveChangesAsync(); if(!await db.Activities.AnyAsync()) { db.Activities.AddRange(new Activity{Actor="Володимир Алексеев",Text="Открыл голосование по плейлисту"},new Activity{Actor="Анна Белова",Text="Добавила комментарий к Midnight City"}); await db.SaveChangesAsync(); } if(!await db.Notifications.AnyAsync()) { db.Notifications.AddRange(new Notification{UserId=leader.Id,Title="Открыто голосование",Text="Осенний квартирник ждёт вашего решения."},new Notification{UserId=leader.Id,Title="Новый комментарий",Text="Анна оставила комментарий к Midnight City."}); await db.SaveChangesAsync(); } var concert=await db.Concerts.OrderBy(x=>x.Id).FirstOrDefaultAsync(); if(concert is null) { concert=new Concert { Title="Осенний квартирник",Date=new DateTime(2026,9,12,19,0,0,DateTimeKind.Utc),Venue="Art Hall, Киев",Description="Концерт Blue Echo",Status="Voting" }; db.Concerts.Add(concert); await db.SaveChangesAsync(); } var current=await db.Tracks.Where(x=>x.ConcertId==concert.Id).ToListAsync(); foreach(var track in current){var marked=System.Text.RegularExpressions.Regex.Match(track.Title,@"^\[S([1-4])\]\s*(.*)");if(marked.Success){track.SetNumber=int.Parse(marked.Groups[1].Value);track.Title=marked.Groups[2].Value.Trim();}if(track.SetNumber is < 1 or > 4)track.SetNumber=1;} var duplicates=current.GroupBy(x=>new{x.SetNumber,Title=x.Title.Trim().ToLowerInvariant(),Artist=x.Artist.Trim().ToLowerInvariant()}).SelectMany(group=>group.OrderBy(x=>x.Id).Skip(1)).ToList(); db.Tracks.RemoveRange(duplicates); current=current.Except(duplicates).ToList(); var repertoire=new[]{(1,"Midnight City","M83","4:03","Am"),(1,"Use Somebody","Kings of Leon","3:51","C"),(1,"Take Me Out","Franz Ferdinand","3:57","Em"),(1,"Mr. Brightside","The Killers","3:43","Db"),(1,"Somebody Told Me","The Killers","3:17","C#m"),(1,"Sex on Fire","Kings of Leon","3:23","E"),(1,"Are You Gonna Be My Girl","Jet","3:34","A"),(1,"Uprising","Muse","5:04","Dm"),(2,"Dreams","The Cranberries","4:31","G"),(2,"Zombie","The Cranberries","5:06","Em"),(2,"Yellow","Coldplay","4:29","B"),(2,"Clocks","Coldplay","5:07","Eb"),(2,"Creep","Radiohead","3:58","G"),(2,"Wonderwall","Oasis","4:18","F#m"),(2,"Chasing Cars","Snow Patrol","4:27","A"),(2,"Counting Stars","OneRepublic","4:17","C#m"),(3,"Enjoy the Silence","Depeche Mode","4:15","Cm"),(3,"Personal Jesus","Depeche Mode","3:46","Em"),(3,"Sweet Dreams","Eurythmics","4:53","Cm"),(3,"Tainted Love","Soft Cell","2:39","Gm"),(3,"Just Can't Get Enough","Depeche Mode","3:45","C"),(3,"Everybody Wants to Rule the World","Tears for Fears","4:11","D"),(3,"Kids","MGMT","5:03","F#m"),(3,"Electric Feel","MGMT","3:49","Em"),(4,"Don't Stop Me Now","Queen","3:29","F"),(4,"I Was Made for Lovin' You","KISS","4:31","D"),(4,"Song 2","Blur","2:02","F"),(4,"Seven Nation Army","The White Stripes","3:52","Em"),(4,"Smells Like Teen Spirit","Nirvana","5:01","F"),(4,"The Pretender","Foo Fighters","4:29","A"),(4,"Fix You","Coldplay","4:55","Eb")}; foreach(var song in repertoire)if(!current.Any(x=>x.SetNumber==song.Item1&&x.Title.Equals(song.Item2,StringComparison.OrdinalIgnoreCase)&&x.Artist.Equals(song.Item3,StringComparison.OrdinalIgnoreCase)))db.Tracks.Add(new Track{ConcertId=concert.Id,SetNumber=song.Item1,Title=song.Item2,Artist=song.Item3,Duration=song.Item4,Key=song.Item5,Position=current.Count(x=>x.SetNumber==song.Item1)+1,Status="Voting"}); await db.SaveChangesAsync(); }
record LoginRequest(string Email,string Password); record RegisterRequest(string Nickname,string Email,string Password,string? Instrument,string? Role); record VoteRequest(string Value); record CommentRequest(string Text); record PushTokenRequest(string Token); record TrackStatusRequest(string Status); record ConcertStatusRequest(string Status); record TrackOrderRequest(List<int> TrackIds); record CreateConcertRequest(string Title,DateTime Date,DateTime? VotingDeadline,string Venue,string? Description,bool SkipDefaultPlaylist=false); record CreateTrackRequest(string Title,string Artist,string Duration,string Key,int SetNumber,int PlaylistId); record CreatePlaylistRequest(string Name);
class BandSetDb(DbContextOptions<BandSetDb> options):DbContext(options) { public DbSet<User> Users=>Set<User>(); public DbSet<Concert> Concerts=>Set<Concert>(); public DbSet<Playlist> Playlists=>Set<Playlist>(); public DbSet<Track> Tracks=>Set<Track>(); public DbSet<Vote> Votes=>Set<Vote>(); public DbSet<Comment> Comments=>Set<Comment>(); public DbSet<BandMember> BandMembers=>Set<BandMember>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<PushToken> PushTokens=>Set<PushToken>(); public DbSet<Activity> Activities=>Set<Activity>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<User>().HasIndex(x=>x.Email).IsUnique();b.Entity<User>().HasIndex(x=>x.Name).IsUnique();b.Entity<PushToken>().HasIndex(x=>x.Token).IsUnique();b.Entity<Vote>().HasIndex(x=>new{x.TrackId,x.UserId}).IsUnique();b.Entity<Playlist>().HasIndex(x=>new{x.ConcertId,x.Name}).IsUnique();} }
class User { public int Id{get;set;} public string Name{get;set;}=""; public string Email{get;set;}=""; public string Password{get;set;}=""; public string Instrument{get;set;}="Музыкант"; public string Role{get;set;}="Musician"; }
class BandMember { public int Id{get;set;} public string Name{get;set;}=""; public string Instrument{get;set;}=""; public string Role{get;set;}="Musician"; }
class Notification { public int Id{get;set;} public int UserId{get;set;} public int? TrackId{get;set;} public int? ConcertId{get;set;} public string Title{get;set;}=""; public string Text{get;set;}=""; public bool IsRead{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
class PushToken { public int Id{get;set;} public int UserId{get;set;} public string Token{get;set;}=""; }
class Activity { public int Id{get;set;} public string Actor{get;set;}=""; public string Text{get;set;}=""; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
class PushService(HttpClient client) { public async Task Send(IEnumerable<string> tokens,string title,string body) { var payload=tokens.Select(token=>new { to=token,sound="default",title,body }).ToArray(); if(payload.Length==0)return; try { await client.PostAsJsonAsync("https://exp.host/--/api/v2/push/send",payload); } catch { /* In-app notification remains available if Expo is temporarily unreachable. */ } } }
class Concert { public int Id{get;set;} public string Title{get;set;}=""; public DateTime Date{get;set;} public DateTime? VotingDeadline{get;set;} public string Venue{get;set;}=""; public string Description{get;set;}=""; public string Status{get;set;}="Draft"; public bool IsFinalized{get;set;} }
class Playlist { public int Id{get;set;} public int ConcertId{get;set;} public string Name{get;set;}=""; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
class Track { public int Id{get;set;} public int ConcertId{get;set;} public int? PlaylistId{get;set;} public int SetNumber{get;set;}=1; public string Title{get;set;}=""; public string Artist{get;set;}=""; public string Duration{get;set;}=""; public string Key{get;set;}=""; public int Position{get;set;} public string Status{get;set;}="Pending"; public string? DropboxFileId{get;set;} }
